// The form stores the upload under a field-specific key; rename it to "invoice" so both paths look the same
return $input.all().map(item => {
  const key = Object.keys(item.binary || {})[0];
  if (!key) throw new Error('No PDF was uploaded');
  return { json: { source: 'Upload form', file_name: item.binary[key].fileName }, binary: { invoice: item.binary[key] } };
});

