// Accounts-payable checks before the invoice goes into the books
const APPROVAL_LIMIT = 2000; // invoices above this amount need a manager's approval
const round = n => Math.round((Number(n) || 0) * 100) / 100;
const close = (a, b) => Math.abs(round(a) - round(b)) <= 0.05;

return $('AI invoice extraction').all().map((item, i) => {
  const inv = item.json.output;
  const file = $('Read PDF text').all()[i]?.json || {};
  const lines = Array.isArray(inv.line_items) ? inv.line_items : [];
  const duplicate = $('Check for duplicate').all().some(d => d.json.invoice_number && String(d.json.invoice_number) === String(inv.invoice_number));
  const issues = [];

  for (const field of ['vendor_name', 'invoice_number', 'invoice_date', 'total']) {
    if (!inv[field]) issues.push(`Missing ${field.replace('_', ' ')}`);
  }
  const linesTotal = lines.reduce((sum, l) => sum + (Number(l.amount) || 0), 0);
  if (lines.length && !close(linesTotal, inv.subtotal)) issues.push(`Line items add up to ${round(linesTotal)}, not the subtotal ${inv.subtotal}`);
  if (!close((Number(inv.subtotal) || 0) + (Number(inv.tax) || 0), inv.total)) issues.push(`Subtotal + tax does not equal the total ${inv.total}`);
  for (const l of lines) {
    if (l.quantity && l.unit_price && !close(l.quantity * l.unit_price, l.amount)) issues.push(`"${l.description}": ${l.quantity} x ${l.unit_price} is not ${l.amount}`);
  }
  if (duplicate) issues.push(`Duplicate: invoice ${inv.invoice_number} is already in the system`);
  if (inv.due_date && inv.due_date < $now.toISODate()) issues.push(`Overdue since ${inv.due_date}`);

  const status = issues.length ? 'Needs review' : round(inv.total) > APPROVAL_LIMIT ? 'Needs approval' : 'Ready to pay';

  return {
    json: {
      processed_at: $now.toISO(),
      invoice_number: inv.invoice_number,
      vendor_name: inv.vendor_name,
      vendor_email: inv.vendor_email,
      invoice_date: inv.invoice_date,
      due_date: inv.due_date,
      currency: inv.currency,
      subtotal: round(inv.subtotal),
      tax: round(inv.tax),
      total: round(inv.total),
      po_number: inv.po_number,
      payment_terms: inv.payment_terms,
      status,
      issues: issues.join('; ') || 'None',
      file_name: file.file_name || $('Read PDF text').all()[i]?.binary?.invoice?.fileName || '',
      line_items: lines,
    },
    pairedItem: { item: i },
  };
});

