// One row per invoice line for the "Invoice line items" tab
// Read the line items from "Validate invoice" (the Sheets append output only holds the saved columns)
return $('Validate invoice').all().flatMap((item, i) =>
  (item.json.line_items || []).map((l, n) => ({
    json: {
      invoice_number: item.json.invoice_number,
      vendor_name: item.json.vendor_name,
      line_no: n + 1,
      description: l.description,
      quantity: l.quantity,
      unit_price: l.unit_price,
      amount: l.amount,
    },
    pairedItem: { item: i },
  }))
);
